 "content": "def transform(grid):
    """Draw a diagonal-then-axial 3-line from marker 1 toward marker 2,
    stopping at the first cell in the 8-neighborhood of marker 2."""
    out = [row[:] for row in grid]
    markers = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                markers[value] = (r, c)
    if 1 not in markers or 2 not in markers:
        return out

    r, c = markers[1]
    tr, tc = markers[2]
    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1

    # Follow the diagonal while both coordinates still have more than one
    # cell to cover; then continue along whichever axis remains farther away.
    while abs(tr - r) > 1 and abs(tc - c) > 1:
        r += dr
        c += dc
        if max(abs(tr - r), abs(tc - c)) > 1:
            out[r][c] = 3

    if abs(tr - r) <= 1:
        while c != tc:
            c += dc
            if max(abs(tr - r), abs(tc - c)) <= 1:
                break
            out[r][c] = 3
    else:
        while r != tr:
            r += dr
            if max(abs(tr - r), abs(tc - c)) <= 1:
                break
            out[r][c] = 3
    return out
