for src,dst in [(start,goal),(goal,start)]:
 for n_diag in range(0,10):
  for h in range(0,13):
   for v in range(0,13):
    for hd,vd in product([-1,1],repeat=2):
     r,c=src; cells=[]
     for _ in range(n_diag): r+=(-1 if dst[0]<r else 1); c+=(-1 if dst[1]<c else 1); cells.append((r,c))
     # straight horizontal then vertical
     for _ in range(h): c+=hd; cells.append((r,c))
     for _ in range(v): r+=vd; cells.append((r,c))
